// Shapes of database/toeic.json (generated by database/build.mjs)

export type Label = 'A' | 'B' | 'C' | 'D';

export interface Question {
  id: string;
  number: number;
  prompt: string | null;
  choices: Partial<Record<Label, string>>;
  answer: Label;
  explanation_vi: string;
  difficulty?: number;
  tags?: string[];
}

export interface Passage {
  type: string;
  title?: string;
  text: string;
}

export interface Graphic {
  type: 'table' | 'bar-chart';
  title: string;
  columns: string[];
  rows: string[][];
}

export interface QuestionSet {
  id: string;
  part: number;
  title?: string;
  passage_type?: string;
  transcript?: string;
  image_description?: string;
  passages?: Passage[];
  graphic?: Graphic;
  audio_url?: string | null;
  audio_duration_sec?: number | null;
  image_url?: string | null;
  questions: Question[];
}

export interface Test {
  id: string;
  title: string;
  test_type: 'full' | 'mini' | 'part-drill';
  format_code: string;
  year?: number;
  duration_minutes?: number;
  description_vi?: string;
  question_count: number;
  sets: QuestionSet[];
}

export interface ExamFormat {
  code: string;
  name: string;
  skills: string;
  total_questions: number;
  duration_minutes: number;
  score_min: number;
  score_max: number;
  score_step: number;
  description_vi: string;
  notes?: string;
  status: 'current' | 'announced' | 'unverified';
}

export interface ExamPart {
  format_code: string;
  section: string;
  part_number: number;
  name_en: string;
  name_vi: string;
  question_count: number;
  question_range: string;
  choices_per_question: number | null;
  description_vi: string;
  skills_tested: string[];
}

export interface ScoreLevel {
  min_score: number;
  max_score: number;
  cefr: string;
  label_vi: string;
  description_vi: string;
}

export interface Vocabulary {
  word: string;
  pos: string;
  ipa: string;
  meaning_vi: string;
  example_en: string;
  example_vi: string;
  topic: string;
  level: string;
  collocations: string[];
}

export interface GrammarTopic {
  slug: string;
  order_index: number;
  title_vi: string;
  title_en: string;
  parts: number[];
  summary_vi: string;
  rules: { rule: string; example: string }[];
  common_traps_vi: string[];
}

export interface Strategy {
  part_number: number | null;
  section: string;
  order_index: number;
  title_vi: string;
  content_vi: string;
}

export interface Source {
  id: string;
  name: string;
  url: string;
  source_type: string;
  note_vi: string | null;
}

export interface Bundle {
  generated_at: string;
  exam_formats: ExamFormat[];
  exam_sections: { format_code: string; name: string; question_count: number; duration_minutes: number; score_min: number; score_max: number }[];
  exam_parts: ExamPart[];
  score_levels: ScoreLevel[];
  score_conversion: { section: 'listening' | 'reading'; correct_answers: number; scaled_score: number }[];
  fees: { country: string; format_code: string; candidate_type: string; amount: number; currency: string; effective_year: number; source_id: string; verified: number }[];
  updates: { date: string; title_vi: string; summary_vi: string; source_id: string; verified: number }[];
  sources: Source[];
  tests: Test[];
  vocabulary: Vocabulary[];
  grammar_topics: GrammarTopic[];
  strategies: Strategy[];
}

export type Section = 'listening' | 'reading';
export type Scope = 'full' | Section;
export type Answers = Record<string, Label>;
